  "settings.retentionMonthlyInfo": "Behåller en säkerhetskopia för var och en av de senaste N kalendermånaderna med en säkerhetskopia.",
  "settings.retentionYearlyInfo": "Behåller en säkerhetskopia för vart och ett av de senaste N kalenderåren med en säkerhetskopia. Finns det färre år behålls även den äldsta.",
  "settings.retentionOffsiteTitle": "Extern lagring",
  "settings.retentionOffsiteHint": "En separat policy för off-site-repot, så att du kan behålla det längre som arkiv. Allt 0 = behåll varje off-site-säkerhetskopia (ingen off-site-rensning).",
  "settings.ownRetentionTitle": "Lagringsregler per källa",
  "settings.ownOffsiteRetention": "Egna lagringsregler för off-site",
  "settings.ownOffsiteRetentionFor": "Egna lagringsregler för off-site för {source}",
  "settings.ownOffsiteRetentionHint": "En källa kan behålla säkerhetskopiorna i sitt off-site-repo enligt egna regler i stället för de gemensamma off-site-reglerna ovan. En källa utan egna regler använder de gemensamma.",
  "settings.ownOffsiteRetentionToggleHint": "På: källans off-site-repo behåller sina säkerhetskopior enligt de fem reglerna nedan, som utgår från de gemensamma off-site-värdena. Av: det använder de gemensamma off-site-reglerna. Allt 0 behåller varje off-site-säkerhetskopia av källan.",
  "settings.retentionExtraTargets": "Ytterligare externa mål behåller sina egna regler, som du ställer in på kortet Extern kopia för varje avsnitt.",
  "settings.retentionOffsiteScope": "Reglerna gäller det primära externa målet för varje avsnitt, alltså adressen i dess off-site-fält. Alla andra externa mål, även ett som skapats från ett mål, behåller sina egna regler. Står det bara nollor där rensar BombVault det aldrig.",
  "settings.retentionCombineInfo": "De fem reglerna kombineras med ELLER: en säkerhetskopia överlever om någon enskild regel skulle behålla den. De summeras inte till ett fast antal. Gäller separat för varje säkerhetskopierad post.",

  // Off-site (rclone)
  "rclone.title": "Off-site (rclone)",
  "rclone.hint": "Klistra in en rclone-konfiguration för att säkerhetskopiera till molnet (Backblaze B2, S3, Google Drive, …). Den lagras krypterad. SMB/NFS behöver ingen rclone: montera resursen på Unraid och peka en säkerhetskopiesökväg mot den.",
  "rclone.configured": "Konfigurerade fjärrlager",
  "rclone.pathHint": "Ange sedan en säkerhetskopiesökväg till ”rclone:<remote>:<bucket>/path” för att skicka det avsnittet off-site.",
  "cloud.title": "Delade molnautentiseringsuppgifter (S3 / restic REST)",
  "cloud.hint": "Uppgifter för fjärrbaserade restic-backender, utan rclone. Ange efter sparande en backup-sökväg till ett fjärrrepo, t.ex. s3:s3.amazonaws.com/bucket/path, rest:http://host:8000/repo eller sftp:user@host:/repo. Hemligheter lagras krypterade och visas inte igen.",
  "cloud.secretSet": "sparat, lämna tomt för att behålla",
  "cloud.storageClass.label": "Off-site-lagringsklass",
  "cloud.storageClass.default": "(leverantörens standard)",
  "cloud.storageClass.hint": "Gäller endast native S3-backends (repositorier som börjar med s3:). Djuparkivnivåer (Glacier Flexible Retrieval, Deep Archive) erbjuds avsiktligt inte eftersom de bryter restic-återställning.",
  "cloud.credSets.title": "Ytterligare autentiseringsuppsättningar",
  "cloud.credSets.hint": "Ge ett eller flera off-site-mål egna S3- eller restic REST-uppgifter, istället för att dela de ovan.",
  "cloud.credSets.add": "Lägg till autentiseringsuppsättning",
  "cloud.credSets.name": "Namn",
  "cloud.credSets.none": "Inga ytterligare autentiseringsuppsättningar än.",
  "cloud.credSets.kept": "{name} (behållna autentiseringsuppgifter)",
  "export.encrypt.hint": "restic-repositorierna är redan krypterade. Detta krypterar valfritt de oskyddade exportartefakterna (container- och VM-tar.gz med deras xml, och flash-zip) med age, så att de kan lagras eller flyttas utanför servern på ett säkert sätt.",
  "export.encrypt.ageInfo": "age (age-encryption.org) är ett litet, modernt filkrypteringsverktyg, ett enklare alternativ till GPG för att försegla en fil åt en eller flera mottagare.",
  "export.encrypt.enable": "Kryptera exporter med age",
  "export.encrypt.enableHint": "När på förseglas container-, VM- och flash-exporter med age innan de skrivs till disk och får ändelsen .age.",
  "export.encrypt.kitSealed": "Återställningskitet förseglas också och kommer som bombvault-recovery-kit.md.age. Det förblir läsbar text (ASCII armor), så det går fortfarande att klistra in i en lösenordshanterare eller skriva ut, men du behöver din privata age-nyckel för att öppna det: förvara den nyckeln någonstans som inte är beroende av kitet självt.",
  "export.encrypt.recipients": "age-mottagare",
  "export.encrypt.recipientsHint": "En mottagare per rad. Använd en age-publik nyckel (age1...) eller en SSH-publik nyckel. Motsvarande privat nyckel behövs för att dekryptera utanför servern. Med kryptering på och ingen giltig mottagare misslyckas exporten istället för att skriva klartext.",
  "export.encrypt.recipientsPlaceholder": "age1qz...\nssh-ed25519 AAAA...",
  "export.encrypt.recipientsRequired": "Lägg till minst en age-mottagare, annars misslyckas den krypterade exporten.",
