  "dbdump.damagedHint": "Den här dumpen klarade inte sina kontroller och kunde inte tas bort automatiskt. Den går varken att hämta eller importera. Radera den.",
  "dbdump.download": "Hämta",
  "dbdump.format": "Filformat",
