  "recovery.abIntro": "Gör arkiven som pluginet Appdata.Backup skrev till återställningspunkter för motsvarande containrar, var och en daterad när pluginet skapade den. Arkiven läses bara, de ändras eller raderas aldrig. Vart och ett packas upp bredvid förrådet, säkerhetskopieras, och den uppackade kopian tas bort igen, så där behövs plats för det största arkivet.",
