  "mcp.endpointLabel": "Slutpunkt",
  "mcp.endpointHint": "Adressen som din assistent ansluter till. Den talar Streamable HTTP och förväntar sig en nyckel i Authorization- eller X-API-Key-huvudet, eller ett åtkomsttoken när assistenten har loggat in via OAuth.",
  "mcp.newKey": "Ny nyckel",
  "mcp.labelLabel": "Nyckelns namn",
  "mcp.labelPlaceholder": "Claude Code på laptopen",
  "mcp.allowStart": "Tillåt att starta säkerhetskopior",
  "mcp.allowStartHint": "Med det här på kan assistenten starta en säkerhetskopia av en post, av ett helt avsnitt eller den totala säkerhetskopian, och avbryta de kopior den själv startat: högst {n} i timmen, {minutes} minuter mellan varje för samma post och {perDay} per post och dag. En säkerhetskopia stoppar körande containers tills den är klar. Med det här av kan nyckeln bara läsa.",
  "mcp.createKey": "Skapa nyckel",
  "mcp.created": "Nyckel skapad",
