  "mcp.limitReached": "one=Det finns redan {n} aktiv nyckel. Återkalla den innan du skapar en ny.|other=Det finns redan {n} aktiva nycklar. Återkalla en innan du skapar en ny.",
  "mcp.newKeyTitle": "Din nya nyckel",
  "mcp.showOnce": "Kopiera den nu. BombVault behåller bara ett fingeravtryck av den och kan inte visa den igen.",
  "mcp.copyKey": "Kopiera nyckel",
  "mcp.dismissKey": "Jag har kopierat den",
  "mcp.snippetsLabel": "Anslut en klient",
