  "mcp.oauthConnectorLabel": "Connector-URL",
  "mcp.oauthConnectorHint": "Ange den här adressen i molnassistenten. Det är MCP-slutpunkten under din offentliga adress, och därifrån hittar assistenten inloggningssidan.",
  "mcp.grantCreated": "Inloggad via OAuth {date}",
  "mcp.revokedReplaced": "Ersatt {date}, när klienten loggade in igen",
  "mcp.revokedExpired": "Utgången {date}, efter 30 dagar utan användning",
