  "mcp.revokedByClient": "Utloggad av klienten {date}",
  "mcp.revokedOAuthOff": "Återkallad {date}, när inloggning via OAuth stängdes av",
  "mcp.revokedOAuthMoved": "Återkallad {date}, när den offentliga adressen ändrades",
  "mcp.stepOAuth": "Slå på inloggning",
  "mcp.setupChatGPT": "Öppna Inställningar, Appar och connectors i ChatGPT och slå på utvecklarläge under Avancerade inställningar. Välj sedan Skapa, ge connectorn ett namn, klistra in connector-URL:en som MCP-server-URL, välj OAuth som autentisering, bekräfta att du litar på den och skapa den.",
  "mcp.setupClaudeAi": "Öppna Inställningar, Connectors på claude.ai och välj Lägg till anpassad connector. Ge den ett namn, klistra in connector-URL:en, lämna OAuth-klient-ID och hemlighet tomma och lägg till den. Välj sedan Anslut.",
  "mcp.copyConnector": "Kopiera connector-URL",
  "mcp.oauthProxyNote": "Tjänsten anropar /mcp, /oauth/ och /.well-known/ från sina egna servrar, så en omvänd proxy med egen inloggning måste släppa igenom de sökvägarna till BombVault.",
