  "mcp.notePerplexity": "Hittills är det bara Perplexitys Mac-app som ansluter till MCP-servrar på din dator eller i ditt nätverk; Windows-appen och webbplatsen gör det inte.",
  "mcp.noteGrok": "Groks dokumentation visar inte formuläret för anslutningar i detalj. Om det bara erbjuder en inloggning och inget fält för en header kan det ännu inte använda en BombVault-nyckel.",
  "mcp.certNotForThisAddress": "BombVaults certifikat nämner inte {host}, så assistenter vägrar ansluta till den här adressen. Lägg till adressen i certifikatet och ladda sedan ner det för utdragen.",
  "mcp.certOwnNotForThisAddress": "Ditt certifikat nämner inte {host}, så assistenter vägrar ansluta till den här adressen. Anslut via ett namn som certifikatet täcker.",
