  "anomaly.settings.title": "Avvikelser",
  "anomaly.settings.hint": "Jämför varje säkerhetskopia av en post med postens egen historik och rapporterar det som inte passar. Körs i bakgrunden efter varje säkerhetskopia och gör ingen långsammare. De flesta kontroller börjar efter 10 säkerhetskopior av en post; fel, omskrivning av det mesta av datan och en nästan tom källa kontrolleras från början. Ledigt utrymme bevakas för lokala repositorier och för rclone-repositorier som rapporterar det; på Unraids användarresurs är det det lediga utrymmet i hela arrayen.",
  "anomaly.settings.toggle": "Upptäck avvikelser",
  "anomaly.settings.sensitivity": "Känslighet",
  "anomaly.settings.sensitivityHint": "Strikt rapporterar även mindre förändringar, Tillåtande bara stora, Balanserad passar de flesta servrar. Varje post kan få en egen inställning under Avvikelser, Övervakning.",
  "anomaly.settings.notifyMin": "Skicka avisering för",
  "anomaly.settings.notifyHint": "Använder kanalerna som är inställda under Aviseringar. Varje post kan ändra det under Avvikelser, Övervakning. Upprepade fel i säkerhetskopior och dumpar och misslyckade schemalagda återställningskontroller skickar redan ett eget meddelande och skickas därför inte en gång till.",
  "anomaly.settings.notifyMuted": "Just nu skickas ingenting: aviseringar är avstängda eller ingen kanal är inställd.",
  "anomaly.settings.openNotifications": "Öppna aviseringsinställningar",
  "anomaly.settings.holdToggle": "Behåll gamla säkerhetskopior när en källa krymper kraftigt eller skrivs om",
  "anomaly.settings.holdHint": "Tre fynd pausar raderingen av gamla säkerhetskopior: en källa som plötsligt är nästan tom, en som har blivit mycket mindre och en säkerhetskopia som sparade det mesta av datan igen, som det ser ut efter utpressningsprogram. Annars skulle lagringen radera de goda äldre säkerhetskopiorna en i taget. Så länge en sådan avvikelse är öppen behålls de gamla säkerhetskopiorna av bara den posten (eller den databasdumpen eller det ZFS-datasetet); allt annat rensas som vanligt. Kvittera avvikelsen eller markera den som väntad för att fortsätta.",
